custom_css:
/* Listening v1.1 2025-10-03优化
主题作者：咩野(DC@lambkinling)
请勿二传，二改请标源，倒卖、商用引流司马;
部分代码来自：KAKAA老师的双色盒子、NARIKI、墨千尾、宝贝龙，特此感谢。 */

/* ❤️‍🔥→调整位置，🐕→自定义修改*/

/* 定位线 调试用
.mes_block,
.mes_block > * {
  outline: 1px solid red;
} 
.mesAvatarWrapper,
.mesAvatarWrapper > * {
  outline: 1px solid blue;
} */

/* ===== 0. 变量定义 ===== */
:root {
    --边框圆角-small: 3px;
    --边框圆角-medium: 5px;
    --头像下方字体颜色: white;
    --阴影: rgba(255, 255, 255, 0.7);
    --毛玻璃效果: 10px; /* 气泡 */
    --模糊程度: 15px;
    --visual-novel-height: 40dvh; /* 视觉小说模式高度调整 */
  /* 🐕↑以上自调整↑🐕 */

    --混合色: color-mix(in srgb, var(--SmartThemeBotMesBlurTintColor) 50%, var(--SmartThemeUserMesBlurTintColor));
    --渐变色-1: var(--SmartThemeUserMesBlurTintColor);
    --渐变色-2: var(--SmartThemeBotMesBlurTintColor);
    --渐变色-3: color-mix(in srgb, var(--SmartThemeEmColor) 50%, black);
}

/* ===== 1. 文本样式 ===== */
/* 对话文本 */
q {
    position: relative;
    color: transparent;
    background:
        linear-gradient(to bottom, 
            var(--SmartThemeEmColor) 0%, 
            var(--SmartThemeQuoteColor) 100%);
    -webkit-text-fill-color: transparent;
    -webkit-background-clip: text;
    -moz-background-clip: text;
    background-clip: text;
    text-shadow: none;
}

/* 斜体 */
em {
    color: var(--SmartThemeBodyColor) !important;
  text-shadow: color-mix(in srgb, var(--SmartThemeEmColor) 40%, transparent); 
    border-radius: 3px;
    text-shadow: 
    0 0 3px var(--SmartThemeEmColor),
    0 0 5px var(--SmartThemeEmColor),
    0 0 10px var(--SmartThemeEmColor);
}

/* 删除文本 */
del, 
s {
    color: red;
    text-shadow: 
    0 0 4px #ff0000,
    0 0 8px #ff0000, 
    0 0 12px #ff0000;
}

/* 代码样式 */
code {
    border-radius: 0;
    border: none;
    background-color: var(--SmartThemeBlurTintColor);
    color: var(--SmartThemeBodyColor) !important;
    box-shadow: 0 0 3px var(--SmartThemeEmColor);
    padding: 0 3px;
    letter-spacing: 0.5px;
    line-height: 1.8;
}

/* 代码块 */
.mes pre code {
    background-color: var(--SmartThemeBlurTintColor);
    border-left: 5px solid var(--SmartThemeQuoteColor);
    border-right: 5px solid var(--SmartThemeEmColor);
    padding: 15px;
    position: relative;
    overflow: auto;
    text-shadow: none !important;
}

.mes pre code::before {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    top: 10px;
    height: 1px;
    background: repeating-linear-gradient(
        to right,
        var(--SmartThemeEmColor),
        var(--SmartThemeEmColor) 10px,
        transparent 10px,
        transparent 20px);
}

.mes pre code::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: 10px;
    height: 1px;
    background: repeating-linear-gradient(
        to right,
        var(--SmartThemeQuoteColor),
        var(--SmartThemeQuoteColor) 10px,
        transparent 10px,
       transparent 20px);
}

/* markdown引用文本 */
blockquote {
    border: none !important;
    background: 
        linear-gradient(to right, 
            transparent 0%,
            var(--渐变色-3) 30%, 
            var(--渐变色-3) 70%, 
            transparent 100%) !important;
    mask: linear-gradient(to bottom, 
            transparent 0%, 
            black 10%,
            black 90%,
            transparent 100%);
    -webkit-mask: linear-gradient(to bottom, 
            transparent 0%, 
            black 10%,
            black 90%,
            transparent 100%);
}

/* 分割线 */
hr {
    background: linear-gradient(
        to right, 
        transparent 0%,
        var(--SmartThemeEmColor) 50%,
        transparent 100%) !important;
}

/* ===== 2. 滚动条 & 滑动条 ===== */
/* 滚动条 */
::-webkit-scrollbar {
    display: none;
}

html {
  scrollbar-width: auto;
  scrollbar-color: var(--混合色) #f1f1f1;
}

/* 滑动条 */
input[type="range"] {
  background: transparent !important;
  color: transparent;
  border-radius: var(--边框圆角-medium);
  filter: none !important;
  box-shadow:
    inset 1px 1px 2px var(--阴影) !important;
}

input[type="range"]::-webkit-slider-thumb { 
    clip-path: polygon(50% 100%, 0 45%, 0 15%, 25% 0, 50% 25%, 75% 0, 100% 15%, 100% 45%); 
    background:  
        linear-gradient(135deg,  
            var(--SmartThemeEmColor) 0%,  
            var(--SmartThemeQuoteColor) 100%); 
    background-color: #fff; 
    border: none; 
    border-radius: 0;
    transform: scale(1.35); 
}

/* ===== 3. 聊天区域 ===== */
 /* 思维链 */
.mes_reasoning_header {
  position: relative;
  border-radius: 30px;
  background: transparent;
  border: none;
  box-shadow: 
      -1px -1px 2px var(--阴影),
      1px 1px 2px var(--阴影);
}

.mes_reasoning_header_title::before {
    position: relative;
    content: "▷ ︎ıllıııllıl ♪"; /* 思维链文字 */
    font-size: var(--mainFontSize);
    z-index: 2;
}

.mes_reasoning_arrow.fa-chevron-up {
    opacity: 0;
}
.mes_reasoning_header_title {
    font-size: 0;
}

.mes_reasoning_header::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 0;
    height: 100%;
    background-image: 
        linear-gradient(to right, 
        var(--渐变色-2) 0%, 
        var(--渐变色-1) 100%);
    transition: width 0.5s ease;
    z-index: 1;
    border-radius: 30px;
}

.mes_reasoning_header:hover::before {
    width: 100%;
}

#sheld {
  top: var(--topBarBlockSize);
  height: calc(100dvh - var(--topBarBlockSize) - 1px);
}



/* --- 聊天框 --- */
#chat {
  align-items: center;
  background: transparent;
  border: none;
}

/* 消息区域 */
.mes {
    flex-direction: column;
    align-items: center;
    padding: 0 15px; /* 气泡框两边空隙 */
    border-radius: var(--边框圆角-small);
    background: transparent;
}

/* 控制消息间距 */
div[is_user="true"] .mes_block {
  margin-top: 30px;
}

/* 最后一条消息与底栏距离 */
.last_mes {
  margin-bottom: 30px !important;
}

.last_mes .mesAvatarWrapper {
  padding-bottom: 0px !important;
}

/* 消息块 */
body .mes_block {
    display: flex;
    position: relative;
    flex-direction: column;
    padding: 6px 10px;
    border-radius: var(--边框圆角-medium);
    border: none;
    background: var(--SmartThemeChatTintColor);
    backdrop-filter: blur(var(--毛玻璃效果)) !important;
    -webkit-backdrop-filter: blur(var(--毛玻璃效果)) !important;
    box-shadow: 0 0 3px var(--阴影);
}

/* 渐变线 */
.mes_block::after {
        content: "";
        position: absolute;
        top: 30px;
        left: 0;
        width: 100%;
        height: 1px;
        background: linear-gradient(to right,
            transparent, 
            var(--阴影),
            transparent);
        z-index: 1;
        opacity: 0.5;
    }
}

/* 提示词拆分 */
.popup-content:has(#showRawPrompt) {
  overflow-y: auto;
}

/* 左右箭头 */
.swipe_right, .swipe_left {
    color: var(--描边);
    box-shadow: 0 0 3px var(--阴影);
}

.swipe_right,
.swipes-counter {
    margin-right: 15px;
}

/* 避免遮挡箭头 */
 .last_mes .mes_block {
  padding-bottom: 40px !important;
}

/* 文本 */
.mes_text {
  padding: 0;
  text-align: justify;
}

/* 小铅笔 */
.mes_button,
.mes_edit_buttons,
.mes .extraMesButtons {
    filter: none !important;
    box-shadow: none !important;
    font-size: var(--mainFontSize);
}

/* 子按钮 */
.mes_edit_buttons .mes_edit_done,
.mes_edit_buttons .mes_edit_copy,
.mes_edit_buttons .mes_edit_add_reasoning,
.mes_edit_buttons .mes_edit_delete,
.mes_edit_buttons .mes_edit_up,
.mes_edit_buttons .mes_edit_down,
.mes_edit_buttons .mes_edit_cancel {
  opacity: 1 !important;
  border: none;
  box-shadow: 0 0 3px var(--阴影) !important;
}

.mes_edit_buttons .mes_edit_delete {
  background-color: red;
}

.mes .ch_name {
    align-items: center;
}

.timestamp {
    font-size: calc(var(--mainFontSize) * 0.75);
}

.ch_name.flex-container.justifySpaceBetween {
  margin-bottom: 5px;
}

/* --- 名字 --- */
/* by NAKARI */
body .mes_block {
    transform: none !important;
    overflow: visible;
}

#chat .name_text {
    position: absolute;
    z-index: 10;
    font-size: calc(var(--mainFontSize) * 0.85);
    &::before {
        content: "@";
    }
}

/* ❤️‍🔥Char - 名字位置 */
div[is_user="false"] .name_text {
    top: calc(0% - 49px); /* 上下 */
    left: calc(50% - 40px); /* 左右 */
    transform: translate(-50%, -50%) ;
}

/* ❤️‍🔥User - 名字位置 */
#chat div[is_user="true"] .name_text {
    bottom: calc(0% - 157px);  /* 上下 */
    right: calc(50% - 35px);  /* 左右 */
    transform: translate(50%, 50%);
}

/* --- 头像区域 --- */
.mesAvatarWrapper {
  display: flex;
  position: relative;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 335px; /* 宽度 */
  padding: 0;
  margin: 0 auto;
}

/* 头像容器 */
.mesAvatarWrapper .avatar {
  position: absolute;
  justify-content: center;
  width: auto;
  pointer-events: none;
  box-shadow: 0 0 2px var(--阴影);
}

.mesAvatarWrapper .avatar img {
  pointer-events: auto;
}

/* 全局头像 */
.avatar img,
body.big-avatar .avatar img {
  box-shadow: none;
  border: none;
}

/* 🐕通用头像框 */
.mesAvatarWrapper .avatar::before {
  content: "";
  position: absolute;
  width: 32px; /* 调整大小 */
  height: 32px;
  background-image: url("https://i.postimg.cc/66S5b6nf/1754884779760.gif"); /* 此处粘贴你的图片URL */
  background-size: cover;
  background-repeat: no-repeat;
  bottom: 18%; /* 上下 */
  right: -15%; /* 左右 */
  transform: translateX(-50%) scale(1.8); /* 调整大小 */
  z-index: 2;
}

/* User - 耳机 */
div[is_user="true"] .mesAvatarWrapper .avatar::after {
  content: "";
  position: absolute;
  width: 40px; /* 调整大小 */
  height: 40px;
  background-image: url("https://i.postimg.cc/5tfcRyq6/21-20250809162149.png");
  filter: brightness(1); /* 🐕白耳机改1,黑耳机改0 */
  background-size: cover;
  background-repeat: no-repeat;
  bottom: 5px; /* 上下 */
  right: -11px; /* 左右 */
  transform: translateX(-50%) scale(1.8);
  z-index: -1;
}

/* Char - 耳机 */
div[is_user="false"] .mesAvatarWrapper .avatar::after {
   content: "";
    position: absolute;
    width: 40px;
    height: 40px;
    background: url("https://i.postimg.cc/wBFK8z0F/21-20250809162207.png");
    filter: brightness(1); /* 🐕黑耳机改成0，白1 */
  background-size: cover;
  background-repeat: no-repeat;
  bottom: 4.3px; /* 上下 */
  right: -18.5px; /* 左右 */
  transform: translateX(-50%) scale(1.8);
  z-index: -1; 
}

/* User - 头像区域 */
div[is_user="true"] .mesAvatarWrapper {
    order: 1;
    display: flex;
    flex-direction: row;
    justify-content: flex-end;
    align-items: flex-end;
    aspect-ratio: 7 / 1;
}

/* ❤️‍🔥User - 头像位置 */
div[is_user="true"] .mesAvatarWrapper .avatar {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
    position: absolute;
    bottom: calc(-50% - 39px); /* 上下 */
    right: calc(50% - 38px); /* 左右 */
    transform: translate(50%, 50%) scale(1.5);  /* scale头像大小 */
}

/* Char - 头像区域 */
div[is_user="false"] .mesAvatarWrapper {
    position: relative;
    margin-bottom: 10px;
    aspect-ratio: 8 / 3.7;
}

/* ❤️‍🔥Char - 头像位置 */
div[is_user="false"] .mesAvatarWrapper .avatar {
  position: absolute;
  transform: translate(-50%, -50%) scale(1.5); 
  left: calc(50% - 39px); /* 左右 */
  top: 42%; /* 上下 */
}

/* 🐕Char - 自定义背景 */
/* div[is_user="false"] .mesAvatarWrapper::after {
  content: "";
  position: absolute;
  z-index: -2;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  background-image: url('https://files.catbox.moe/lhlwia.png');
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
  border-radius: var(--边框圆角-medium);
  box-shadow: 
    0 0 3px var(--阴影),
    0 0 3px var(--阴影);
} */

/* 🐕Char - 头像下方自定义文字 */
div[is_user="false"] .mesAvatarWrapper::before {
  content: "✩ ⋆ ┄ ⋆ 我和你，最天生一对 ⋆ ┄ ⋆ ✩ ";
  white-space: pre;
  position: absolute;
  z-index: 1;
  bottom: 10%;
  font-size: 0.85em;
  text-align: center;
}

/* 楼层、计时器、tokens */
.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: flex;
  position: relative;
  align-items: center;
  color: var(--SmartThemeQuoteColor);
  opacity: 1 !important;
}

.mesIDDisplay:empty,
.mes_timer:empty,
.tokenCounterDisplay:empty{
  display: none !important;
}

/* User - 楼层、词符数 */
/* 五角星 */
div[is_user="true"] .mesAvatarWrapper .mesIDDisplay::before {
  content: "";
  display: inline-block;
  width: 1.4em;
  height: 1.4em;
  margin-right:  1px;
  background-color: transparent;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path fill="gold" d="M12 17.27L18.18 21l-1.64-7.03L22 9.24l-7.19-.61L12 2 9.19 8.63 2 9.24l5.46 4.73L5.82 21z"/></svg>');
  background-size: contain;
}

/* 爱心 */
div[is_user="true"] .mesAvatarWrapper .tokenCounterDisplay::before {
  content: "";
  display: inline-block;
  width: 1.3em;
  height: 1.3em;
  margin: 0 1px 0 6px;
  background-color: transparent;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80" viewBox="0 0 24 24"><path fill="%23ff0000" d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>');
  background-size: contain;
}

div[is_user="true"] .mesIDDisplay:hover::before,
div[is_user="true"] .tokenCounterDisplay:hover::before {
  filter: grayscale(100%) brightness(0.7);
}

/* 头像下方字体 */
.name_text,
div[is_user="true"] .tokenCounterDisplay,
div[is_user="true"] .mesIDDisplay,
div[is_user="false"] .mesAvatarWrapper::before,
div[is_user="false"] .mesIDDisplay::before,
div[is_user="false"] .mes_timer::before,
div[is_user="false"] .tokenCounterDisplay::before,
div[is_user="false"] .mesIDDisplay::after,
div[is_user="false"] .mes_timer::after,
div[is_user="false"] .tokenCounterDisplay::after {
  color: var(--头像下方字体颜色);
  text-shadow: 
      0 0 5px var(--SmartThemeQuoteColor),
      0 0 3px var(--SmartThemeQuoteColor),
      0 0 1px var(--SmartThemeQuoteColor);
}

/* 🐕Char - 元信息(文字自定义) */
/* 楼层 */
div[is_user="false"] .mesAvatarWrapper .mesIDDisplay::before {
  content: "共同喜欢 ";
}

div[is_user="false"] .mesAvatarWrapper .mesIDDisplay::after {
  content: " 首歌";
}

/* 计时器 */
div[is_user="false"] .mesAvatarWrapper .mes_timer::before {
  content: "距离 ";
}

div[is_user="false"] .mesAvatarWrapper .mes_timer::after {
  content: " 公里，";
}

/* 词符数 */
div[is_user="false"] .mesAvatarWrapper .tokenCounterDisplay::before {
  content: "一起听了 ";
}

div[is_user="false"] .mesAvatarWrapper .tokenCounterDisplay::after {
  content: " 小时，";
}

/* Char - 楼层、计时器、词符数 */
div[is_user="false"] .mesAvatarWrapper > :not(.avatar) {
  display: flex;
  flex-wrap: wrap; 
  align-self: flex-end;
}

/* 调整排序 */
div[is_user="false"] .mesAvatarWrapper > .mesIDDisplay { order: 3; }
div[is_user="false"] .mesAvatarWrapper > .mes_timer { order: 1; }
div[is_user="false"] .mesAvatarWrapper > .tokenCounterDisplay { order: 2; }

/* 为每个子项添加最小宽度 */
div[is_user="false"] .mesAvatarWrapper .mesIDDisplay,
div[is_user="false"] .mesAvatarWrapper .mes_timer,
div[is_user="false"] .mesAvatarWrapper .tokenCounterDisplay {
  min-width: max-content;
}

/* ❤️‍🔥 - 💓跳动的心 */
div[is_user="true"].mes::before {
  content: "";
  position: absolute;
  bottom: calc(0% - 41px);  /* 上下 */
  right: calc(50% - 20px); /* 左右 */
  transform: translate(-50%, 50%);
  width: 40px;  /* 大小调整 */
  height: 40px;
  background-color: transparent;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80" viewBox="0 0 24 24"><path fill="%23ff0000" d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/></svg>'); /* 颜色修改fill= */
  background-size: contain;
  filter: drop-shadow(0 0 2px #ff0000); /* 外发光 */
  animation: twinkle 3s ease infinite;
}

@keyframes twinkle {
  0%, 100% { transform: scale(1.05); opacity: 0.6; }
  25% { transform: scale(1.15); opacity: 0.9; }
  50% { transform: scale(1); opacity: 0.7; }
  75% { transform: scale(1.15); opacity: 0.8; }
}

/* ===== 5. 顶栏 & 底栏区域 ===== */
/* 底栏 */
#form_sheld {
  margin: 0 auto;
  position: sticky;
  bottom: 1px; /* 底栏高度 */
}

#send_form,
body.no-blur #send_form {
  width: 98%; /* 宽度 */
  border-radius: var(--边框圆角-medium);
  border: 3px solid var(--SmartThemeBorderColor) !important;
  outline: 1px solid var(--混合色) !important;
  box-shadow: none;
  background: color-mix(in srgb, var(--SmartThemeBlurTintColor) 1%, transparent) !important;
  backdrop-filter: blur(var(--模糊程度)) !important;
  -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
}

#send_form:hover, 
body.no-blur #send_form:hover {
  transform: translateY(-5px);
}

/* 顶栏 */
#top-bar,
body.no-blur #top-bar {
  align-items: center;
  width: 99%;
  top: 2px;
  border-radius: var(--边框圆角-medium);
  border: 2px solid var(--SmartThemeBorderColor);
  outline: 1px solid var(--混合色) !important;
  box-shadow: none;
  background: color-mix(in srgb, var(--SmartThemeBlurTintColor) 75%, transparent) !important;
  backdrop-filter: blur(var(--模糊程度)) !important;
  -webkit-backdrop-filter: blur(var(--模糊程度)) !important;
}

/* 顶栏 & 底栏图标 */
.drawer-icon,
#send_form .fa-solid,
#quick-reply-rocket-button {
  display: flex;
  overflow: visible;
  transform-origin: center;
  justify-content: center;
  opacity: 0.7 !important;
  font-size: calc(var(--mainFontSize) * 1.2);
  text-shadow: none !important;
  background: 
    linear-gradient(125deg, 
    var(--渐变色-2) 0%, 
    var(--渐变色-1) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  transition: all 0.5s ease;
}

.drawer-icon:hover, 
.drawer-icon.openIcon {
  overflow: visible;
  position: relative;
  font-size: calc(var(--mainFontSize) * 1.6);
  background: 
    linear-gradient(165deg, 
    var(--渐变色-1) 0%, 
    var(--渐变色-2) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

#send_form .fa-solid,
#quick-reply-rocket-button {
  font-size: calc(var(--mainFontSize) * 1.5);
  text-shadow: none !important;
}

.fa-solid:not(#load-spinner) {
  text-shadow: none !important;
